<?php	/**	* Fecha: 20/11/2013	* Descripción: Procesa una tabla Ordena, Filtra y Pagina segun la consulta MySQL recibida.	* Comentarios: Este archivo trabaja en conjunto con jquery datatable. Recibe parametros utilizados	* por datatables y devuelve en forma aceptada por la misma.	**/	require_once('Connection.php');	require_once('GetSession.php');	if ($SessionAuthenticated != 'SI'){		DestroySession();		print 'EXIT';		exit();	}	/*Incluimos la libreria que va utilizar para obtener la consulta*/	if(isset($_POST['Source']) && file_exists($_POST['Source'])) {		include  $_POST['Source'];	}else{		$Output = array(			'Status'    => 'ERROR',			'Error'     => 'No existe el formulario a invocar'		);		print_r($Output);		exit();	}	/*Obtenemos la configuracion de la tabla.*/	if(function_exists($_POST['Function'])){		$GetTableConfig = $_POST['Function'];		if(isset($_POST['Params']) && $_POST['Params'] != ''){			$Params = json_decode(Decrypt($_POST['Params'], $SessionRandom), TRUE);			$TableConfig    = $GetTableConfig($Params);		}else{			$TableConfig    = $GetTableConfig();		}	}else{		$Output = array(			'Status'    => 'ERROR',			'Error'     => 'No existe al funcion que intenta invocar'		);		print_r($Output);		exit();	}	if(isset($_POST['Privileges']) && $_POST['Privileges'] == 'GetPrivileges' && isset($_POST['RouteForm']) && $_POST['RouteForm'] != ''){		$RouteForm = (stripos($_POST['RouteForm'], '.php') !== false ? $_POST['RouteForm']:$_POST['RouteForm'] . '.php');		/*Se Obtienen los privilegios del rol*/		$PrivilegesGroup    = GetFormPrivileges($RouteForm, $SessionGroupId, 2);		/*Se Obtienen los privilegios del usuario*/		$PrivilegesUser     = GetFormPrivileges($RouteForm, $SessionUserId, 3);		$Privileges = array_merge($PrivilegesGroup, $PrivilegesUser);	}else{		//print_r($_POST['Privileges']);		$Privileges = $_POST['Privileges'];	}	/*$RouteForm = (stripos($_POST['RouteForm'], '.php') !== false ? $_POST['RouteForm']:$_POST['RouteForm'] . '.php');	/*Se Obtienen los privilegios del rol* /	$PrivilegesGroup    = GetFormPrivileges($RouteForm, $SessionGroupId, 2);	/*Se Obtienen los privilegios del usuario* /	$PrivilegesUser     = GetFormPrivileges($RouteForm, $SessionUserId, 3);	$Privileges = array_merge($PrivilegesGroup, $PrivilegesUser);*/	$MyTable        = ($TableConfig['Table']['Alias'] != '' ? $TableConfig['Table']['Alias']:$TableConfig['Table']['TableName']);	$IndexColumn    = ($TableConfig['Index']['Alias'] != '' ? $TableConfig['Index']['Alias']:$TableConfig['Index']['IndexName']);	$Where          = $TableConfig['Condition'];	$MyColumns      = '';	//print_r($TableConfig);	if(isset($TableConfig['UsePrivileges'])){		$Privileges = $TableConfig['UsePrivileges'];	}	for($Colum = 0; $Colum < count($TableConfig['Columns']); $Colum++){		switch($TableConfig['Columns'][$Colum]['Type']){			case 0:			case 2:				$MyColumns .= ($TableConfig['Columns'][$Colum]['Alias'] != '' ? $TableConfig['Columns'][$Colum]['ColumName'] . ' AS ' . $TableConfig['Columns'][$Colum]['Alias']:$TableConfig['Columns'][$Colum]['ColumName']) . ', ';				break;			case 1:				$MyColumns .= "'', ";				break;			default:				$MyColumns .= '';				break;		}	}	$MyColumns = substr_replace($MyColumns, '', -2);	/*--- Paginación ---*/	$Limit = '';	if (isset($_POST['iDisplayStart']) && $_POST['iDisplayLength'] != '-1')	{		$Limit = 'LIMIT ' . intval($_POST['iDisplayStart']) . ', ' . intval($_POST['iDisplayLength']);		/*SE ajecuta la consulta que estable a cer la variable NumRow.*/		$QueryNumRow = 'SET @NUM_ROW=' . $_POST['iDisplayStart'] . ';';		$ResultNumRow = $Connection->query($QueryNumRow);		$CountRow=$_POST['iDisplayStart'];	}else{		/*SE ajecuta la consulta que estable a cer la variable NumRow.*/		$QueryNumRow = 'SET @NUM_ROW=0;';		$ResultNumRow = $Connection->query($QueryNumRow);		$CountRow = 0;	}	/*--- Ordenamiento ---*/	$Order = '';	if (isset($_POST['iSortCol_0'])){		$Order = 'ORDER BY  ';  /*Se deben dejar siempre dos espacios al final para evita error en la condición (Linea 100)*/		for ($i = 0; $i < intval($_POST['iSortingCols']); $i++){			if ($_POST['bSortable_' . intval($_POST['iSortCol_' . $i])] == 'true'){				if($TableConfig['Columns'][intval($_POST['iSortCol_' . $i])]['Alias'] != ''){					$ColumName = $TableConfig['Columns'][intval($_POST['iSortCol_' . $i])]['Alias'];				}else{					$ColumName = $TableConfig['Columns'][intval($_POST['iSortCol_' . $i])]['ColumName'];				}				$Order .= $ColumName . ' ' . ($_POST['sSortDir_' . $i] === 'asc' ? 'ASC':'DESC') . ', ';			}		}		$Order = substr_replace($Order, '', -2);	}	if($Order == ''){		if($TableConfig['Order'] == ''){			$Order = 'ORDER BY ' . $IndexColumn . ' DESC';		}else{			$Order = 'ORDER BY ' . $TableConfig['Order'];		}	}	/*--- Agrupados ---*/	$Group = ($TableConfig['Group'] != '' ? 'GROUP BY ' . $TableConfig['Group']:'');	/*---Busqueda General---*/	if (isset($_POST['sSearch']) && $_POST['sSearch'] != '' ){		if ($Where == ''){			$Where = ' (';		}else{			$Where .= ' AND (';		}		for ($i = 0; $i < count($TableConfig['Columns']); $i++){			if($TableConfig['Columns'][$i]['Type'] == 2)				$Where .= $TableConfig['Columns'][$i]['ColumName'] . ' LIKE "%' . MysqlClear($_POST['sSearch']) . '%" OR ';		}		$Where = substr_replace($Where, '', -4);		$Where .= ')';		RecordLog($MyTable, '', 4, $SessionUserId, $_POST['sSearch']);	}	/*--Filtro individual por columna--*/	for ($i = 0; $i < count($TableConfig['Columns']); $i++){		$Search = '';		if(isset($_POST['bSearchable_' . $i]) && $_POST['bSearchable_' . $i] == 'true' && $_POST['sSearch_' . $i] != ''){			$Search = $_POST['sSearch_' . $i];			if($TableConfig['Columns'][$i]['Type'] == 2){				if ($Where == ""){					$Where = ' (';				}else{					$Where .= ' AND (';				}				$SearchTemp = explode('/@&/', $Search); /*el simbolo /@&/ es un delimitador estandar para seprara*/														/* buscquedas multiples en una sola cadena*/				$Search     = '';				for($iS = 0; $iS < count($SearchTemp); $iS++){					$Search .= $TableConfig['Columns'][$i]['ColumName'] . ' LIKE "%' . MysqlClear($SearchTemp[$iS]) . '%" OR ';				}				$Search = substr_replace($Search, '', -4) . ')';				$Where .= $Search;				RecordLog($MyTable, ($TableConfig['Columns'][$i]['Alias'] != '' ? $TableConfig['Columns'][$i]['Alias']:$TableConfig['Columns'][$i]['ColumName']), 4, $SessionUserId, $_POST['sSearch_' . $i]);			}		}	}	$Query  = ' SELECT SQL_CALC_FOUND_ROWS @NUM_ROW:=@NUM_ROW+1 AS NUM_ROW, ' . $IndexColumn . ', ' . $MyColumns . '				FROM ' . ($TableConfig['Table']['Alias'] != '' ? $TableConfig['Table']['TableName'] . ' AS ' .$TableConfig['Table']['Alias']:$TableConfig['Table']['TableName']) . '				WHERE					' . ($Where == '' ? '1 = 1 ':$Where) . ' '. $Group . ' '. $Order . ' '. $Limit . ';';	if(!$Result = $Connection -> query($Query)){		$Output = array(			'sEcho'                 => intval($_POST['sEcho']),			'iTotalRecords'         => 0,			'iTotalDisplayRecords'  => 0,			'Debug'                 => array(),			'aaData'                => array()		);		if($TableConfig['Debug'] == 1){			$Output['Debug']['Query']   = $Query;			$Output['Debug']['Result']  = print_r($Connection, true);		}		$Response= array('Response' => $Output);		print json_encode($Response);		exit();	}	/*--Total de datos en limite--*/	$iFilteredTotal = GetValue('SELECT FOUND_ROWS() as Total','Total');	/*--Total de datos en la tabla --*/	$Admin  =   strtoupper(					GetValue(						sprintf('SELECT `Nombre` FROM CelaRol WHERE `id` = %s;',							GetSQLValueString($SessionGroupId, 'int')						),						'Nombre'					)				);	if($Admin == "DEVELOPER" || $Admin == "DESARROLLADOR"){		$iTotal =   GetValue(						sprintf('SELECT COUNT(%s) as Total FROM %s;',							$IndexColumn,							($TableConfig['Table']['Alias'] != '' ? $TableConfig['Table']['TableName'] . ' AS ' .$TableConfig['Table']['Alias']:$TableConfig['Table']['TableName'])						),						'Total'					);	}else{		$iTotal =   GetValue(						sprintf('SELECT COUNT(%s) as Total FROM %s WHERE %s;',							$IndexColumn,							($TableConfig['Table']['Alias'] != '' ? $TableConfig['Table']['TableName'] . ' AS ' .$TableConfig['Table']['Alias']:$TableConfig['Table']['TableName']),							($TableConfig['Condition'] == '' ? ' 1=1 ':$TableConfig['Condition'])						),						'Total'					);	}	$Output = array(		'sEcho'                 => intval($_POST['sEcho']),		'iTotalRecords'         => $iTotal,		'iTotalDisplayRecords'  => $iFilteredTotal,		'Query'                 => Encrypt($Query, $SessionRandom),		'Debug'                 => array(),		'aaData'                => array()	);	if($TableConfig['Debug'] == 1){		$Output['Debug']['Query']   = $Query;		$Output['Debug']['Result']  = print_r($Connection, true);	}	/*Se genera el arreglo con los datos obtenidos.*/	while ($Record = $Result -> fetch_array(MYSQLI_ASSOC)){		$Row                = array();		$Row['DT_RowClass'] = '';		$Row['DT_RowId']    = '';		for ($i = 0; $i < count($TableConfig['Columns']); $i++){			switch ($TableConfig['Columns'][$i]['Type']){				case 2:					$ColumName = trim(($TableConfig['Columns'][$i]['Alias'] != '' ? $TableConfig['Columns'][$i]['Alias']:$TableConfig['Columns'][$i]['ColumName']));					if($TableConfig['Columns'][$i]['Render'] != ''){						/*Incluimos el render de las columnas.*/						$ColumRender = trim($TableConfig['Columns'][$i]['Render']);						include('RenderColumn.php');						if(isset($Render[$ColumRender])){							if(mb_detect_encoding($Render[$ColumRender], 'UTF-8', true) === false)								$Field = utf8_encode($Render[$ColumRender]);							else								$Field = $Render[$ColumRender];							$Row[$i] = $Field;						}else{							$Row[$i] = '&nbsp;';						}					}else{						if(mb_detect_encoding($Record[$ColumName], 'UTF-8', true) === false)							$Field = utf8_encode($Record[$ColumName]);						else							$Field = $Record[$ColumName];						$Row[$i] = $Field;					}					break;				case 1;					if($TableConfig['Columns'][$i]['Extra'] != ''){						/*Incluimos las columnas extras.*/						$ColumExtra = $TableConfig['Columns'][$i]['Extra'];						include('ExtraColumns.php');						if(isset($Extra[$ColumExtra])){							if(mb_detect_encoding($Extra[$ColumExtra], 'UTF-8', true) === false)								$Field = utf8_encode($Extra[$ColumExtra]);							else								$Field = $Extra[$ColumExtra];							$Row[$i] = $Field;						}else{							$Row[$i] = '&nbsp;';						}					}else{						$Row[$i] = '&nbsp;';					}					break;				default:					$Row[$i] = '&nbsp;';					break;//				case 2://					$ColumName = trim(($TableConfig['Columns'][$i]['Alias'] != '' ? $TableConfig['Columns'][$i]['Alias']:$TableConfig['Columns'][$i]['ColumName']));//					if($TableConfig['Columns'][$i]['Render'] != ''){//						/*Incluimos el render de las columnas.*///						$ColumRender = trim($TableConfig['Columns'][$i]['Render']);//						include('RenderColumn.php');//						$Row[$i] = (isset($Render[$ColumRender]) ? $Render[$ColumRender]:'&nbsp;');//					}else{//						$Row[$i] = $Record[$ColumName];//					}//					break;//				case 1;//					if($TableConfig['Columns'][$i]['Extra'] != ''){//						/*Incluimos las columnas extras.*///						$ColumExtra = $TableConfig['Columns'][$i]['Extra'];//						include('ExtraColumns.php');//						$Row[$i] = (isset($Extra[$ColumExtra]) ? $Extra[$ColumExtra]:'&nbsp;');//					}else{//						$Row[$i] = '&nbsp;';//					}//					break;//				default://					$Row[$i] = '&nbsp;';//					break;			}		}		if($TableConfig['RenderRow'] != ''){			$RendeRow = trim($TableConfig['RenderRow']);			/*Incluimos las columnas con render.*/			include('RenderRow.php');			/*Formato para una columna con valor en la tabla pero de algun estilo en especial*/			$Row['DT_RowClass'] = $Rows[$RendeRow];		}		$Row['DT_RowId']    = $MyTable . $Record[$IndexColumn];		$Row['DT_RowClass'] .= ' dataTableRow ';		$Output['aaData'][] = $Row;		$CountRow++;	}	$Response= array('Response' => $Output);	$Connection->close();	print json_encode($Response);?>